// Package cldr holds the Unicode CLDR data internal/i18n formats with: plural
// rules, number symbols and patterns, the short compact-decimal patterns, the
// narrow US dollar symbol, the Gregorian patterns and names Timlee uses,
// relative-time patterns and the short millisecond, second and minute units.
//
// tables.go is generated by gen.go from a pinned release of
// github.com/unicode-org/cldr-json, the data browsers' Intl uses, so a page
// formatted here and later updated by Intl in the browser does not change.
// Only the formatting locales Timlee ships are generated. To add one, list it
// in gen.go and run:
//
//	go generate ./internal/i18n/cldr
//
// The data is © Unicode, Inc., under the Unicode License v3
// (https://www.unicode.org/license.txt).
package cldr

//go:generate go run gen.go

// Plural categories in CLDR order; a [Categories]string is indexed by them.
const (
	Zero = iota
	One
	Two
	Few
	Many
	Other
	Categories
)

// CategoryNames are the CLDR keywords of the plural categories, by index.
var CategoryNames = [Categories]string{"zero", "one", "two", "few", "many", "other"}

// Relative-time units, indexing Locale.Relative.
const (
	Second = iota
	Minute
	Hour
	Day
	RelativeUnits
)

// Duration units, indexing Locale.Units.
const (
	Millisecond = iota
	UnitSecond
	UnitMinute
	DurationUnits
)

// Locale is the data of one formatting locale. Strings are CLDR's own,
// including its pattern syntax; a pattern missing for a plural category is ""
// and falls back to Other.
type Locale struct {
	// PluralRules are the cardinal plural conditions by category, in CLDR
	// rule syntax without the samples. Other is empty: it is what is left.
	PluralRules [Categories]string

	// Number symbols of the Latin numbering system.
	Decimal, Group, PercentSign, PlusSign, MinusSign, Infinity, NaN string
	// MinimumGroupingDigits is how many digits must precede the first
	// grouping separator before one is written at all.
	MinimumGroupingDigits int

	// Number patterns: decimalFormats, percentFormats and currencyFormats,
	// "standard" width.
	DecimalPattern, PercentPattern, CurrencyPattern string
	// USD is the narrow symbol of the US dollar.
	USD string
	// Compact[m] are the short compact-decimal patterns for 10^m by plural
	// category. "0" means the magnitude is not abbreviated.
	Compact [][Categories]string

	// Months are the abbreviated month names, format context, January first.
	Months [12]string
	// AM and PM are the abbreviated day periods, format context.
	AM, PM string
	// DateMedium is dateFormats/medium; MonthDay is the MMMd skeleton;
	// TimeShort is timeFormats/short.
	DateMedium, MonthDay, TimeShort string
	// DateTimeMedium is DateMedium and TimeShort joined by
	// dateTimeFormats/medium; MonthDayTime is MonthDay and a two-digit hour
	// and minute in the locale's hour cycle, joined the same way.
	DateTimeMedium, MonthDayTime string

	// Relative[unit][0] are the future patterns ("in {0} minutes") and
	// Relative[unit][1] the past ones, long width.
	Relative [RelativeUnits][2][Categories]string
	// Units are the short unit patterns ("{0} ms").
	Units [DurationUnits][Categories]string
}
